import z3

# Variables
edges = {(i,j): z3.Bool(f'e_{i}_{j}') for i in range(15) for j in range(i+1,15)}

# Colors: 0 to 3
colors = [z3.Int(f'c_{i}') for i in range(15)]

# Solver
s = z3.Solver()

# Color constraints: 0 <= c < 4
for c in colors:
    s.add(c >= 0, c < 4)

# Adjacent different colors
for i in range(15):
    for j in range(i+1,15):
        s.add(z3.Implies(edges[(i,j)], colors[i] != colors[j]))

# Min degree >=5
for v in range(15):
    deg = []
    for u in range(15):
        if u < v:
            deg.append(edges[(u,v)])
        elif u > v:
            deg.append(edges[(v,u)])
    s.add(z3.Sum([z3.If(d,1,0) for d in deg]) >= 5)

# No K5: for every 5 vertices, at least one missing edge
from itertools import combinations
for clique in combinations(range(15),5):
    missing = []
    for a,b in combinations(clique,2):
        missing.append(z3.Not(edges[tuple(sorted((a,b)))]))
    s.add(z3.Or(missing))

# Check satisfiability
print(s.check())

if s.check() == z3.sat:
    m = s.model()
    edge_list = []
    for i in range(15):
        for j in range(i+1,15):
            if m.evaluate(edges[(i,j)]):
                edge_list.append((i,j))
    print(edge_list)
    print(len(edge_list))
